def tr_lower(s):
    """Türkçe kurallarına göre küçük harfe çevirir."""
    result = []
    for ch in s:
        if ch == 'I':
            result.append('ı')
        elif ch == 'İ':
            result.append('i')
        elif 'A' <= ch <= 'Z':
            result.append(chr(ord(ch) + 32))
        else:
            result.append(ch)
    return ''.join(result)


def tr_upper(s):
    """Türkçe kurallarına göre büyük harfe çevirir."""
    result = []
    for ch in s:
        if ch == 'i':
            result.append('İ')
        elif ch == 'ı':
            result.append('I')
        elif 'a' <= ch <= 'z':
            result.append(chr(ord(ch) - 32))
        else:
            result.append(ch)
    return ''.join(result)


def tr_sorted(words):
    """Kelimeleri Türk alfabesine göre sıralar. Girdi listesi değişmez."""
    # Türkçe karakter sırası
    turkish_order = "0123456789abcçdefgğhıijklmnoöpqrsştuüvwxyz"

    def custom_key(word):
        # Kelimenin küçük harfe çevrilmiş hali
        lower_word = tr_lower(word)

        # Özel karakterler (boşluk, noktalama vb.) için sıralama
        # Türkçe listede olmayan karakterler önce gelir, kendi aralarında Unicode'e göre
        def custom_char_key(ch):
            if ch in turkish_order:
                return (0, turkish_order.index(ch))
            else:
                # Türkçe listede olmayan karakterler
                # Unicode kod noktasına göre sıralanır
                return (1, ord(ch))

        # Kelimenin her karakteri için özel anahtar oluştur
        char_keys = [custom_char_key(ch) for ch in lower_word]

        # Kelimenin uzunluğu (kısa olan önce gelir)
        length = len(lower_word)

        return (length, char_keys)

    # Orijinal listeyi değiştirmediği bir kopya oluştur
    words_copy = list(words)

    # Anahtara göre sırala
    return sorted(words_copy, key=custom_key)

